<?php$link = mysqli_connect('localhost', 'root', '');if (!$link) {    die('Could not connect: ' . mysqli_error());}if (!mysqli_select_db("villgro_ais")) {    echo "Unable to select mydbname: " . mysqli_error();    exit;}$result = mysqli_query("SELECT master_name FROM  master_settings where master_name like '" . $_GET['part'] . "%'");while ($row = mysqli_fetch_array($result)) {    $colors[] = $row['master_name'];}mysqli_free_result($result);mysqli_close($link);echo json_encode($colors);